intro='''
function introduction(){return `<header class="platform-intro"><img class="brand-logo" src="data:image/png;base64,LOGO" alt="Groupe UGECAM — Soigner, rééduquer, réinsérer : la santé sans préjugés"><h1>Bienvenue sur la plateforme MOAD DUI</h1><p>Cette plateforme accompagne l’expérimentation menée par la <strong>DNGU et l’équipe DUI du Groupe UGECAM</strong> autour des usages du dossier usager informatisé Airmes. Elle permet de recueillir l’autodiagnostic des établissements, de suivre son avancement et de consulter les informations sur les sites et les ESMS/services.</p><p>Les <strong>référents des ESMS</strong> — direction, encadrement, référents DUI… — sont invités à compléter le questionnaire d’autodiagnostic pour leur établissement.</p><div class="scope-info"><strong>Qui peut consulter les réponses ?</strong><p>Les référents habilités du siège peuvent consulter les réponses des sites de leur UGECAM ; la DNGU dispose d’une vue nationale. Les référents en ESMS accèdent uniquement aux réponses de leur site et, le cas échéant, des autres sites placés sous leur responsabilité. Ils ne peuvent pas consulter l’autodiagnostic des autres établissements.</p></div></header>`}
function accessStage(requests){return requests.some(r=>r.STATUT==='Validé')?'validated':requests.some(r=>r.STATUT==='À valider')?'pending':'form'}
function selectPersonal(){const personal=S.contacts.flatMap(r=>{if(typeof r.MON_PROFIL_JSON!=='string'||!r.MON_PROFIL_JSON)return [];try{const c=JSON.parse(r.MON_PROFIL_JSON);return c&&+c.id===+r.id?[c]:[]}catch{return []}});S.self=!S.owner&&personal.length===1?personal[0]:null;S.email=S.self?.EMAIL||''}
function stateRefreshButton(){return '<button type="button" id="refresh-status" class="status-refresh">Actualiser le statut</button><p id="access-status-error" role="status"></p>'}
function bindStatusRefresh(){const b=document.getElementById('refresh-status');if(b)b.onclick=()=>refreshAccessStatus(true)}
async function refreshAccessStatus(manual=false){if(S.checking||S.sending)return;S.checking=true;try{const [requests,contacts]=await Promise.all([ft('DEMANDES_ACCES'),ft('CONTACTS')]);S.requests=requests;S.contacts=contacts;selectPersonal();const next=accessStage(S.owner?[]:requests);if(next!==S.stage||manual&&next!=='form')show()}catch(e){if(manual){const m=document.getElementById('access-status-error');if(m)m.textContent='Actualisation impossible : '+e.message}}finally{S.checking=false}}
function validatedState(r){const c=S.self||{},name=[c.PRENOM||r.PRENOM,c.NOM||r.NOM].filter(Boolean).join(' '),ug=S.u.find(u=>+u.id===+(c.UGECAM||r.UGECAM))?.UGECAM||'',profile=c.DNGU?'DNGU':c.SIEGE?'SIEGE':r.PROFIL_ACCES||'SITE',sites=[...new Set([+(c.SITE_PRINCIPAL||r.SITE_AIRMES),...list(c.SITES_RESP_AIRMES||r.SITES_RESP_AIRMES)])].filter(Boolean).map(id=>S.s.find(s=>+s.id===id)?.NOM).filter(Boolean),scope=profile==='DNGU'?'Tous les sites du Groupe UGECAM':profile==='SIEGE'?'Tous les sites de votre UGECAM':sites.join(', ')||'Selon les sites validés par l’administrateur';return `<section class="access-state validated"><span class="state-tag">Accès validé</span><h2>Votre demande d’accès a été validée</h2><p>Vous pouvez utiliser les pages autorisées dans le menu à gauche. Le questionnaire est disponible dans <strong>AUTODIAGNOSTIC</strong>.</p><dl class="access-details"><dt>Professionnel</dt><dd>${esc(name||'Votre compte Grist')}</dd><dt>UGECAM</dt><dd>${esc(ug||'Selon votre rattachement validé')}</dd><dt>Profil</dt><dd>${esc(profile==='DNGU'?'DNGU':profile==='SIEGE'?'Siège UGECAM':'Référent ESMS / site')}</dd><dt>Périmètre Autodiag</dt><dd>${esc(scope)}</dd></dl><p>Pour corriger vos informations ou votre rattachement, contactez l’administrateur MOAD.</p>${stateRefreshButton()}</section>`}
'''.replace('LOGO',logo)
